const runId = Number((($json.query) || {}).simulation_run_id);
if (!Number.isInteger(runId) || runId <= 0) {
  return [{ json: { _error: 'Ungueltige oder fehlende simulation_run_id.' } }];
}
return [{ json: { simulation_run_id: runId, _error: null } }];

// Nur ein ABGESCHLOSSENER Walk-Forward-Lauf ist als Explorationsgrundlage sinnvoll -
// ein laufender Lauf hat unvollstaendige Trades, ein Out-of-Sample-Lauf selbst als
// Quelle zu nehmen waere methodisch zirkulaer (er soll ja etwas ANDERES bestaetigen).
const ctx = $('Validiere simulation_run_id').all()[0].json;
if (ctx._error) return [{ json: { _error: ctx._error } }];
const rows = $input.all().map(i => i.json).filter(r => r && r.id !== undefined);
if (rows.length === 0) {
  return [{ json: { _error: 'Lauf ' + ctx.simulation_run_id + ' nicht gefunden oder nicht als abgeschlossener Walk-Forward-Lauf verfuegbar.' } }];
}
const run = rows[0];
return [{ json: { simulation_run_id: run.id, source_run_name: run.name, source_end_date: run.end_date, _error: null } }];

// Welle 3, AP9: Mindestfallzahlen-/OOS-/Konzentrations-Einordnung EXAKT
// deterministisch - die KI bekommt diese Einordnung als feste Vorgabe und
// darf sie nicht selbst neu bewerten (gleiches Prinzip wie 09).
function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Berlin',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(date);
}

const _cfgByKey = {};
for (const r of $('DB: Lern-Konfiguration laden').all().map(i => i.json)) _cfgByKey[r.config_key] = Number(r.value_numeric);
const MIN_SAMPLE = _cfgByKey.LEARNING_MIN_TRADE_SAMPLE_SIZE || 30;
// FIX 2026-08-02 (Fehleranalyse F7): ambiguous_pct war bisher nur informativ - jetzt echtes
// Gate. Konservativer Default 20% falls kein Konfigwert gesetzt ist (sql/043).
const MAX_AMBIGUOUS_PCT = _cfgByKey.hasOwnProperty('MAX_AMBIGUOUS_PCT_FOR_PROPOSAL') && !isNaN(_cfgByKey.MAX_AMBIGUOUS_PCT_FOR_PROPOSAL) ? _cfgByKey.MAX_AMBIGUOUS_PCT_FOR_PROPOSAL : 20.0;

const rows = $input.all().map(i => i.json).filter(r => r.dimension);
const byStrategyTicker = rows.filter(r => r.dimension === 'strategy_ticker');
// FIX 2026-08-02 (Fehleranalyse F6): analog zur bestehenden Ticker-Konzentrationspruefung -
// dominiert ein einzelnes Marktregime das Ergebnis dieser Strategie?
const byStrategyRegime = rows.filter(r => r.dimension === 'strategy_regime');
const overall = $('SQL: Gesamtkennzahlen (Trades)').first().json;

// OOS-Bestaetigung (Auftragsvorgabe: "Out-of-Sample-Ergebnis vorhanden"):
// verlangt einen ABGESCHLOSSENEN out_of_sample-Backtest-Lauf. Aktuell IMMER leer
// (Backtesting-Modul ist mangels Historie dormant, siehe
// docs/BACKTESTING_UND_WALK_FORWARD.md) - das ist beabsichtigt und fuehrt dazu, dass in
// dieser fruehen Systemphase KEIN Vorschlag automatisch entsteht, auch wenn die Fallzahl
// rechnerisch ausreichen wuerde.
// FIX 2026-08-01 (Fehleranalyse F4, kritisch): vorher ein einziges globales Boolean fuer
// ALLE Strategien/Regime zusammen - sobald irgendwann EIN abgeschlossener OOS-Backtest fuer
// z.B. "breakout" existiert, haette das faelschlich auch "mean_reversion" oder eine
// strategy_regime-Kombination OOS-bestaetigt, fuer die nie ein Test lief. Jetzt je Strategie
// geprueft (trading.backtest_runs.strategy_filter) - ein Lauf ohne konkreten strategy_filter
// (z.B. ein globaler Baseline-Test) bestaetigt bewusst KEINE einzelne Strategie.
// Vollstaendige Versionsbindung (rule_version/configuration_version) ist noch nicht
// umgesetzt, da die einzelnen Findings aktuell keine eigene Versionsangabe tragen - siehe
// FEHLERANALYSE.md.
// Verschaerft gegenueber 09b (Live-Variante): bei simulationsbasierten Vorschlaegen muss der
// Out-of-Sample-Lauf ZEITLICH NACH dem Explorationszeitraum liegen (start_date > Quelllauf-
// end_date) - eine blosse Existenzpruefung wuerde erlauben, denselben oder einen frueheren
// Zeitraum als "Bestaetigung" zu missbrauchen, was keine echte Out-of-Sample-Validierung waere.
const sourceRun = $('Pruefe Quell-Lauf').all()[0].json;
const oosRuns = $('DB: OOS-Backtests laden').all().map(i => i.json);
const oosConfirmedStrategies = new Set(
  oosRuns.filter(r => r.strategy_filter && r.start_date && sourceRun.source_end_date && r.start_date > sourceRun.source_end_date)
    .map(r => r.strategy_filter)
);
function oosConfirmedFor(strategy) { return oosConfirmedStrategies.has(strategy); }

const findings = [];
for (const d of rows) {
  if (d.dimension === 'strategy_ticker') continue; // nur fuer die Konzentrationspruefung, kein eigener Vorschlagskandidat
  const n = Number(d.sample_size) || 0;
  if (n < 10) continue; // keine belastbare Aussage -> komplett ausgeblendet

  // Konzentrationspruefung: dominiert ein einzelner Ticker das Ergebnis dieser
  // Strategie? (Auftragsvorgabe: "Effekt nicht nur durch einen einzelnen
  // Ticker verursacht")
  const tickerRows = byStrategyTicker.filter(t => t.value === d.value);
  const totalTickerTrades = tickerRows.reduce((s, t) => s + (Number(t.sample_size) || 0), 0);
  const maxTickerTrades = tickerRows.reduce((m, t) => Math.max(m, Number(t.sample_size) || 0), 0);
  const dominiertVonEinemTicker = totalTickerTrades > 0 && (maxTickerTrades / totalTickerTrades) > 0.5;

  // FIX 2026-08-02 (Fehleranalyse F6): gleiche Pruefung wie oben, aber je Marktregime statt
  // je Ticker (Auftragsvorgabe: Effekt nicht nur durch ein einzelnes Marktregime verursacht).
  const regimeRowsForStrategy = byStrategyRegime.filter(rg => rg.value === d.value);
  const totalRegimeTrades = regimeRowsForStrategy.reduce((s, rg) => s + (Number(rg.sample_size) || 0), 0);
  const maxRegimeTrades = regimeRowsForStrategy.reduce((m, rg) => Math.max(m, Number(rg.sample_size) || 0), 0);
  const dominiertVonEinemRegime = totalRegimeTrades > 0 && (maxRegimeTrades / totalRegimeTrades) > 0.5;

  const level = n < MIN_SAMPLE ? 'niedrig' : (n < MIN_SAMPLE * 3 ? 'mittel' : 'hoch');
  const expR = d.expectancy_r === null ? null : Number(d.expectancy_r);
  // FIX 2026-08-01 (Fehleranalyse F4): oosConfirmed jetzt strategiebezogen statt global.
  const oosConfirmed = oosConfirmedFor(d.value);
  const ambiguousPctValue = d.ambiguous_pct === null ? null : Number(d.ambiguous_pct);
  const eligible = n >= MIN_SAMPLE && oosConfirmed && !dominiertVonEinemTicker && !dominiertVonEinemRegime
    && (ambiguousPctValue === null || ambiguousPctValue <= MAX_AMBIGUOUS_PCT)
    && expR !== null && (expR <= -0.15 || expR >= 0.3);

  // Welle 3, Grundregel 9: die KI darf keine Kennzahl erfinden oder berechnen -
  // Vorschlagstyp UND proposed_value werden deshalb HIER deterministisch
  // vorgegeben, die KI (siehe "Baue Lernagent-Prompt") darf nur noch je
  // Kandidat interpretieren/formulieren und begruenden, ob er trotz
  // bestandener Zahlen-Gates sinnvoll ist - nicht die Zahlen selbst waehlen.
  let candidateProposal = null;
  if (eligible && d.dimension === 'strategy') {
    if (expR <= -0.15) {
      // FIX 2026-08-02 (Fehleranalyse F12): proposed_value war hier immer null - TEXT NOT NULL-
      // Spalte, INSERT waere fehlgeschlagen (identischer Fehler wie der von F5 bereits
      // behobene regime_restriction-Fall). 'inaktiv' ist der deterministische Gegenwert zu
      // current_value:'aktiv', keine erfundene Kennzahl.
      candidateProposal = { proposal_type: 'strategy_deactivation', target_type: d.value, target_value: d.value, current_value: 'aktiv', proposed_value: 'inaktiv', reason_template: 'Strategie ' + d.value + ' zeigt bei n=' + n + ' geschlossenen Trades einen Erwartungswert von ' + expR + 'R (deutlich negativ, nicht durch einen Einzeltitel oder ein einzelnes Marktregime dominiert, OOS-bestaetigt).' };
    } else {
      // FIX 2026-08-02 (Fehleranalyse F12): threshold_adjustment hatte denselben NULL-Fehler,
      // aber im Unterschied zu strategy_deactivation existiert hier keine deterministische
      // Formel fuer den Zielwert ("moderat erhoehen" ist keine berechenbare Zahl) - Grundregel
      // 9 verbietet der KI, das selbst zu beziffern. Bewusst deaktiviert statt einen Wert zu
      // erfinden, bis eine echte Formel/Konfiguration entworfen ist (siehe FEHLERANALYSE.md F9).
      candidateProposal = null;
    }
  } else if (eligible && d.dimension === 'strategy_regime' && expR <= -0.15) {
    // FIX 2026-08-01 (Fehleranalyse F5, mittel): vorher wurde hier auch fuer den POSITIVEN
    // Fall (expR >= 0.3, durch "eligible" mit erlaubt) ein 'regime_restriction'-Kandidat mit
    // proposed_value:null erzeugt - semantisch falsch (eine gut performende Kombination als
    // Restriktion vorgeschlagen) und fuehrte spaeter zu einem NOT-NULL-Konflikt beim
    // Speichern. Kandidat entsteht jetzt nur noch fuer den tatsaechlich negativen Fall.
    candidateProposal = { proposal_type: 'regime_restriction', target_type: d.value, target_value: d.sub_value, current_value: null, proposed_value: 0.1, reason_template: 'Strategie ' + d.value + ' im Regime ' + d.sub_value + ' zeigt bei n=' + n + ' Trades einen Erwartungswert von ' + expR + 'R.' };
  }

  findings.push({
    dimension: d.dimension, value: d.value, sub_value: d.sub_value,
    sample_size: n, expectancy_r: expR,
    median_r: d.median_r === null ? null : Number(d.median_r),
    win_rate_pct: d.win_rate_pct === null ? null : Number(d.win_rate_pct),
    profit_factor: d.profit_factor === null ? null : Number(d.profit_factor),
    ambiguous_pct: d.ambiguous_pct === null ? null : Number(d.ambiguous_pct),
    distinct_tickers: Number(d.distinct_tickers) || 0,
    dominiert_von_einem_ticker: dominiertVonEinemTicker,
    confidence_level: level,
    oos_confirmed: oosConfirmed,
    proposal_eligible: eligible && candidateProposal !== null,
    candidate_proposal: candidateProposal
  });
}

return [{ json: {
  analysis_to: getBusinessDate(),
  closed_trades: Number(overall.closed_trades) || 0,
  blocked_trades: Number(overall.blocked_trades) || 0,
  ambiguous_pct_overall: overall.ambiguous_pct === null ? null : Number(overall.ambiguous_pct),
  expectancy_r_overall: overall.expectancy_r === null ? null : Number(overall.expectancy_r),
  profit_factor_overall: overall.profit_factor === null ? null : Number(overall.profit_factor),
  win_rate_pct_overall: overall.win_rate_pct === null ? null : Number(overall.win_rate_pct),
  min_sample_size: MIN_SAMPLE,
  // FIX 2026-08-01 (Fehleranalyse F4, Folgekorrektur): oos_confirmed ist jetzt eine
  // Zusammenfassung (mindestens eine Strategie OOS-bestaetigt) statt des alten globalen
  // Booleans - die tatsaechliche Gate-Pruefung erfolgt je Finding oben (oos_confirmed pro
  // Zeile ueber oosConfirmedFor(d.value)).
  oos_confirmed: oosConfirmedStrategies.size > 0,
  oos_confirmed_strategies: Array.from(oosConfirmedStrategies),
  findings
} }];

function getAiText(resp) {
  if (typeof resp === 'string') return resp;
  if (resp && Array.isArray(resp.output)) {
    const msg = resp.output.find(o => o.type === 'message');
    const part = msg && Array.isArray(msg.content) ? msg.content.find(c => c.type === 'output_text') : null;
    if (part && part.text) return part.text;
  }
  return JSON.stringify(resp || '');
}
function parseObj(text) {
  let t = String(text || '').trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
  try { const p = JSON.parse(t); return (p && typeof p === 'object') ? p : null; } catch (e) {}
  const s = t.indexOf('{'); const e = t.lastIndexOf('}');
  if (s >= 0 && e > s) { try { return JSON.parse(t.substring(s, e + 1)); } catch (err) {} }
  return null;
}

const base = $('Baue Lernagent-Prompt (Trades)').all()[0].json;
const parsed = parseObj(getAiText($json)) || { decisions: [] };

// Sicherheitsnetz: jede KI-Entscheidung wird gegen die deterministisch
// vorbereiteten candidate_proposal-Kandidaten gematcht - eine Entscheidung
// ohne passenden Kandidaten wird ignoriert, ein Kandidat ohne KI-Entscheidung
// wird NICHT automatisch vorgeschlagen (konservativ: explizites include=true
// noetig).
const eligibleMap = new Map(
  base.findings.filter(f => f.proposal_eligible).map(f => [f.dimension + '|' + f.value + '|' + String(f.sub_value), f])
);

const safeProposals = [];
for (const dec of (Array.isArray(parsed.decisions) ? parsed.decisions : [])) {
  if (dec.include !== true) continue;
  const key = String(dec.dimension) + '|' + String(dec.value) + '|' + String(dec.sub_value);
  const match = eligibleMap.get(key);
  if (!match || !match.candidate_proposal) continue;
  const cp = match.candidate_proposal;
  safeProposals.push({
    proposal_type: cp.proposal_type, target_type: cp.target_type, target_value: cp.target_value,
    current_value: cp.current_value, proposed_value: cp.proposed_value,
    sample_size: match.sample_size, metric_name: 'expectancy_r', metric_value: match.expectancy_r,
    reason: (dec.reason ? String(dec.reason) + ' ' : '') + cp.reason_template,
    confidence_level: match.confidence_level,
    evidence: { win_rate_pct: match.win_rate_pct, profit_factor: match.profit_factor, median_r: match.median_r, ambiguous_pct: match.ambiguous_pct, distinct_tickers: match.distinct_tickers, oos_confirmed: match.oos_confirmed }
  });
}

return [{ json: { ...base, proposals_final: safeProposals } }];

function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgJson(v) { return `'` + JSON.stringify(v === undefined ? null : v).replace(/'/g, `''`) + `'::jsonb`; }

// REPARATUR P2.10 (Lernvorschlaege dauerhaft speichern, 2026-08-03): der INSERT war
// bisher bedingungslos - derselbe Befund (gleiche Zieldimension/-wert) haette bei jedem
// erneuten Lauf, solange die Statistik weiter zutrifft, eine weitere, inhaltsgleiche
// "proposed"-Zeile angelegt, bevor die vorherige ueberhaupt geprueft/freigegeben/abgelehnt
// wurde (12 - Lernvorschlag-Freigabe haette dann mehrere Duplikate parallel zur Wahl gehabt).
// INSERT...SELECT + WHERE NOT EXISTS verhindert das, solange fuer denselben Zielwert bereits
// ein offener (status='proposed') Vorschlag existiert - bereits aktivierte/abgelehnte
// Vorschlaege blockieren einen neuen Vorschlag bewusst NICHT (die Situation kann sich seit
// der letzten Entscheidung geaendert haben).
const j = $json;
const sourceRunId = $('Pruefe Quell-Lauf').all()[0].json.simulation_run_id;
const sql = `INSERT INTO trading.learning_rule_proposals
  (proposal_type, target_type, target_value, current_value, proposed_value, sample_size, metric_name, metric_value, reason, confidence_level, status, metadata_json, rule_version, configuration_version, data_schema_version, learning_model_version, data_source, source_run_id)
SELECT ${pgStr(j.proposal_type)}, ${pgStr(j.target_type)}, ${pgStr(j.target_value)}, ${pgStr(j.current_value)}, ${pgStr(j.proposed_value)},
          ${pgNum(j.sample_size)}, ${pgStr(j.metric_name)}, ${pgNum(j.metric_value)}, ${pgStr(j.reason)}, ${pgStr(j.confidence_level)},
          'proposed', ${pgJson(j.evidence || {})},
          ${pgStr('welle3-lernagent-trades-rules-v1')}, ${pgStr('welle3-lernagent-trades-config-v1')}, ${pgStr('sql-001-v1')}, ${pgStr('09c-handelsstrategien-simulation-v1')},
          'simulation', ${pgNum(sourceRunId)}
WHERE NOT EXISTS (
  SELECT 1 FROM trading.learning_rule_proposals p
  WHERE p.proposal_type = ${pgStr(j.proposal_type)} AND p.target_type = ${pgStr(j.target_type)}
    AND p.target_value = ${pgStr(j.target_value)} AND p.status = 'proposed'
);`;
return { json: { ...j, sql } };

function pgStr(v) { return v === null || v === undefined ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }

function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit' }).format(date);
}

const j = $json;
const sql = `INSERT INTO trading.agent_runs
  (run_id, agent_name, agent_role, model_name, prompt_version, input_reference, output_reference, status, started_at, finished_at)
  VALUES (${pgStr('lernagent-handel-sim-' + getBusinessDate() + '-' + $('Pruefe Quell-Lauf').all()[0].json.simulation_run_id)}, 'lernagent-handelsstrategien-simulation', 'lernen',
          'gpt-5.4-mini', 'lernagent-handel-v1', ${pgStr(j.analysis_to)},
          ${pgStr((j.proposals_final || []).length + ' Vorschlaege')}, 'success', now(), now());`;
return { json: { ...j, sql } };

const j = $('Agentenlauf protokollieren (Trades, SQL bauen)').item.json;
const lines = [
  '📈 Lernagent Handelsstrategien (SIMULATION, Lauf ' + $('Pruefe Quell-Lauf').all()[0].json.simulation_run_id + ') – Stand ' + j.analysis_to,
  '',
  'Geschlossene Simulations-Trades: ' + j.closed_trades + ' (blockiert: ' + j.blocked_trades + ')',
  'Erwartungswert gesamt: ' + (j.expectancy_r_overall ?? 'n/a') + 'R, Profit Factor: ' + (j.profit_factor_overall ?? 'n/a') + ', Trefferquote: ' + (j.win_rate_pct_overall ?? 'n/a') + '%',
  'Anteil mehrdeutiger Ausfuehrungen: ' + (j.ambiguous_pct_overall ?? 'n/a') + '%',
  'Out-of-Sample-Bestaetigung vorhanden: ' + (j.oos_confirmed ? 'ja' : 'nein') + ' (ohne OOS-Bestaetigung entstehen KEINE Vorschlaege, unabhaengig von der Fallzahl)',
  'Mindestfallzahl je Segment: ' + j.min_sample_size,
  '',
  'Vorschlaege diese Woche: ' + (j.proposals_final || []).length
];
for (const p of (j.proposals_final || [])) {
  lines.push('  - [' + p.proposal_type + '] ' + p.target_type + (p.target_value ? '/' + p.target_value : '') + ': ' + (p.current_value ?? '-') + ' -> ' + (p.proposed_value ?? '(kategorisch)') + ' (n=' + p.sample_size + ', Erwartungswert ' + (p.metric_value ?? 'n/a') + 'R) ' + p.reason);
}
if ((j.proposals_final || []).length === 0) lines.push('  (keine belastbaren Vorschlaege - ' + (j.oos_confirmed ? 'Fallzahl/Konzentrations-Gates nicht erfuellt' : 'Backtesting-Modul noch dormant, keine Out-of-Sample-Bestaetigung moeglich') + ')');

return { json: { ...j, report_text: lines.join('\n') } };

// FIX 2026-08-02 (Fehleranalyse F12, Teil 2): der INSERT-Node oben laeuft mit
// onError:continueRegularOutput weiter, ohne dass ein Fehlschlag irgendwo sichtbar wird -
// dieser Ast im Graphen war bisher eine Sackgasse. Keine Graph-Aenderung an bestehenden
// Verbindungen, nur ein zusaetzlicher, rein lesender Pruef-Node am bereits offenen Ende.
const j = $json;
if (j.error) {
  console.warn('09b: Lernvorschlag-INSERT fehlgeschlagen fuer proposal_type=' + (j.proposal_type || '?') + ' target_type=' + (j.target_type || '?') + ' target_value=' + (j.target_value || '?') + ': ' + JSON.stringify(j.error).slice(0, 300));
}
return { json: j };

// PLATZHALTER statt echtem KI-Node (Absturzrisiko frisch importierter LangChain-
// Nodes ueber die API, gleiches Muster wie Workflow 16b - siehe dortigen Commit-
// Kommentar). Der vollstaendige Prompt liegt in $json.systemPrompt/$json.userPrompt
// (von 'Baue Lernagent-Prompt (Trades)' unveraendert uebernommen).
//
// SPAETER MANUELL ERSETZEN: echten 'Message a model'-Node (n8n-nodes-langchain.openAi,
// gleiche Konfiguration wie im Live-Workflow 09b, Credential 'OpenAI account') einfuegen,
// System-Message = {{ $json.systemPrompt }}, User-Message = {{ $json.userPrompt }}.
//
// Bis dahin: konservativer deterministischer Platzhalter-Entscheid - jeder Kandidat mit
// candidate_proposal wird MIT einer generischen Begruendung uebernommen (include=true),
// NICHTS wird erfunden/bewertet, was nicht schon deterministisch vorlag (Grundregel 9
// bleibt gewahrt - der Platzhalter ersetzt nur die redaktionelle Formulierung/das
// fachliche Ermessen der KI, nicht die Zahlen-Gates selbst).
const d = $json;
const decisions = (d.findings || []).filter(f => f.proposal_eligible).map(f => ({
  dimension: f.dimension, value: f.value, sub_value: f.sub_value, include: true,
  reason: '[Platzhalter, keine KI-Bewertung] Automatisch uebernommen, da alle deterministischen Gates (Fallzahl/OOS/Konzentration/Erwartungswert) erfuellt sind.'
}));
return { json: { output: [{ type: 'message', content: [{ type: 'output_text', text: JSON.stringify({ decisions }) }] }] } };

const j = $('Lernbericht aufbereiten (Trades)').all()[0].json;
const runId = $('Pruefe Quell-Lauf').all()[0].json.simulation_run_id;
return { json: { ok: true, simulation_run_id: runId, proposals_count: (j.proposals_final || []).length, report_text: j.report_text } };

const runId = Number((($json.query) || {}).simulation_run_id);
if (!Number.isInteger(runId) || runId <= 0) {
  return [{ json: { _error: 'Ungueltige oder fehlende simulation_run_id.' } }];
}
return [{ json: { simulation_run_id: runId, _error: null } }];

// Nur ein ABGESCHLOSSENER Walk-Forward-Lauf ist als Explorationsgrundlage sinnvoll -
// ein laufender Lauf hat unvollstaendige Trades, ein Out-of-Sample-Lauf selbst als
// Quelle zu nehmen waere methodisch zirkulaer (er soll ja etwas ANDERES bestaetigen).
const ctx = $('Validiere simulation_run_id').all()[0].json;
if (ctx._error) return [{ json: { _error: ctx._error } }];
const rows = $input.all().map(i => i.json).filter(r => r && r.id !== undefined);
if (rows.length === 0) {
  return [{ json: { _error: 'Lauf ' + ctx.simulation_run_id + ' nicht gefunden oder nicht als abgeschlossener Walk-Forward-Lauf verfuegbar.' } }];
}
const run = rows[0];
return [{ json: { simulation_run_id: run.id, source_run_name: run.name, source_end_date: run.end_date, _error: null } }];

// Welle 3, AP9: Mindestfallzahlen-/OOS-/Konzentrations-Einordnung EXAKT
// deterministisch - die KI bekommt diese Einordnung als feste Vorgabe und
// darf sie nicht selbst neu bewerten (gleiches Prinzip wie 09).
function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', {
    timeZone: 'Europe/Berlin',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(date);
}

const _cfgByKey = {};
for (const r of $('DB: Lern-Konfiguration laden').all().map(i => i.json)) _cfgByKey[r.config_key] = Number(r.value_numeric);
const MIN_SAMPLE = _cfgByKey.LEARNING_MIN_TRADE_SAMPLE_SIZE || 30;
// FIX 2026-08-02 (Fehleranalyse F7): ambiguous_pct war bisher nur informativ - jetzt echtes
// Gate. Konservativer Default 20% falls kein Konfigwert gesetzt ist (sql/043).
const MAX_AMBIGUOUS_PCT = _cfgByKey.hasOwnProperty('MAX_AMBIGUOUS_PCT_FOR_PROPOSAL') && !isNaN(_cfgByKey.MAX_AMBIGUOUS_PCT_FOR_PROPOSAL) ? _cfgByKey.MAX_AMBIGUOUS_PCT_FOR_PROPOSAL : 20.0;

const rows = $input.all().map(i => i.json).filter(r => r.dimension);
const byStrategyTicker = rows.filter(r => r.dimension === 'strategy_ticker');
// FIX 2026-08-02 (Fehleranalyse F6): analog zur bestehenden Ticker-Konzentrationspruefung -
// dominiert ein einzelnes Marktregime das Ergebnis dieser Strategie?
const byStrategyRegime = rows.filter(r => r.dimension === 'strategy_regime');
const overall = $('SQL: Gesamtkennzahlen (Trades)').first().json;

// OOS-Bestaetigung (Auftragsvorgabe: "Out-of-Sample-Ergebnis vorhanden"):
// verlangt einen ABGESCHLOSSENEN out_of_sample-Backtest-Lauf. Aktuell IMMER leer
// (Backtesting-Modul ist mangels Historie dormant, siehe
// docs/BACKTESTING_UND_WALK_FORWARD.md) - das ist beabsichtigt und fuehrt dazu, dass in
// dieser fruehen Systemphase KEIN Vorschlag automatisch entsteht, auch wenn die Fallzahl
// rechnerisch ausreichen wuerde.
// FIX 2026-08-01 (Fehleranalyse F4, kritisch): vorher ein einziges globales Boolean fuer
// ALLE Strategien/Regime zusammen - sobald irgendwann EIN abgeschlossener OOS-Backtest fuer
// z.B. "breakout" existiert, haette das faelschlich auch "mean_reversion" oder eine
// strategy_regime-Kombination OOS-bestaetigt, fuer die nie ein Test lief. Jetzt je Strategie
// geprueft (trading.backtest_runs.strategy_filter) - ein Lauf ohne konkreten strategy_filter
// (z.B. ein globaler Baseline-Test) bestaetigt bewusst KEINE einzelne Strategie.
// Vollstaendige Versionsbindung (rule_version/configuration_version) ist noch nicht
// umgesetzt, da die einzelnen Findings aktuell keine eigene Versionsangabe tragen - siehe
// FEHLERANALYSE.md.
// Verschaerft gegenueber 09b (Live-Variante): bei simulationsbasierten Vorschlaegen muss der
// Out-of-Sample-Lauf ZEITLICH NACH dem Explorationszeitraum liegen (start_date > Quelllauf-
// end_date) - eine blosse Existenzpruefung wuerde erlauben, denselben oder einen frueheren
// Zeitraum als "Bestaetigung" zu missbrauchen, was keine echte Out-of-Sample-Validierung waere.
const sourceRun = $('Pruefe Quell-Lauf').all()[0].json;
const oosRuns = $('DB: OOS-Backtests laden').all().map(i => i.json);
const oosConfirmedStrategies = new Set(
  oosRuns.filter(r => r.strategy_filter && r.start_date && sourceRun.source_end_date && r.start_date > sourceRun.source_end_date)
    .map(r => r.strategy_filter)
);
function oosConfirmedFor(strategy) { return oosConfirmedStrategies.has(strategy); }

const findings = [];
for (const d of rows) {
  if (d.dimension === 'strategy_ticker') continue; // nur fuer die Konzentrationspruefung, kein eigener Vorschlagskandidat
  const n = Number(d.sample_size) || 0;
  if (n < 10) continue; // keine belastbare Aussage -> komplett ausgeblendet

  // Konzentrationspruefung: dominiert ein einzelner Ticker das Ergebnis dieser
  // Strategie? (Auftragsvorgabe: "Effekt nicht nur durch einen einzelnen
  // Ticker verursacht")
  const tickerRows = byStrategyTicker.filter(t => t.value === d.value);
  const totalTickerTrades = tickerRows.reduce((s, t) => s + (Number(t.sample_size) || 0), 0);
  const maxTickerTrades = tickerRows.reduce((m, t) => Math.max(m, Number(t.sample_size) || 0), 0);
  const dominiertVonEinemTicker = totalTickerTrades > 0 && (maxTickerTrades / totalTickerTrades) > 0.5;

  // FIX 2026-08-02 (Fehleranalyse F6): gleiche Pruefung wie oben, aber je Marktregime statt
  // je Ticker (Auftragsvorgabe: Effekt nicht nur durch ein einzelnes Marktregime verursacht).
  const regimeRowsForStrategy = byStrategyRegime.filter(rg => rg.value === d.value);
  const totalRegimeTrades = regimeRowsForStrategy.reduce((s, rg) => s + (Number(rg.sample_size) || 0), 0);
  const maxRegimeTrades = regimeRowsForStrategy.reduce((m, rg) => Math.max(m, Number(rg.sample_size) || 0), 0);
  const dominiertVonEinemRegime = totalRegimeTrades > 0 && (maxRegimeTrades / totalRegimeTrades) > 0.5;

  const level = n < MIN_SAMPLE ? 'niedrig' : (n < MIN_SAMPLE * 3 ? 'mittel' : 'hoch');
  const expR = d.expectancy_r === null ? null : Number(d.expectancy_r);
  // FIX 2026-08-01 (Fehleranalyse F4): oosConfirmed jetzt strategiebezogen statt global.
  const oosConfirmed = oosConfirmedFor(d.value);
  const ambiguousPctValue = d.ambiguous_pct === null ? null : Number(d.ambiguous_pct);
  const eligible = n >= MIN_SAMPLE && oosConfirmed && !dominiertVonEinemTicker && !dominiertVonEinemRegime
    && (ambiguousPctValue === null || ambiguousPctValue <= MAX_AMBIGUOUS_PCT)
    && expR !== null && (expR <= -0.15 || expR >= 0.3);

  // Welle 3, Grundregel 9: die KI darf keine Kennzahl erfinden oder berechnen -
  // Vorschlagstyp UND proposed_value werden deshalb HIER deterministisch
  // vorgegeben, die KI (siehe "Baue Lernagent-Prompt") darf nur noch je
  // Kandidat interpretieren/formulieren und begruenden, ob er trotz
  // bestandener Zahlen-Gates sinnvoll ist - nicht die Zahlen selbst waehlen.
  let candidateProposal = null;
  if (eligible && d.dimension === 'strategy') {
    if (expR <= -0.15) {
      // FIX 2026-08-02 (Fehleranalyse F12): proposed_value war hier immer null - TEXT NOT NULL-
      // Spalte, INSERT waere fehlgeschlagen (identischer Fehler wie der von F5 bereits
      // behobene regime_restriction-Fall). 'inaktiv' ist der deterministische Gegenwert zu
      // current_value:'aktiv', keine erfundene Kennzahl.
      candidateProposal = { proposal_type: 'strategy_deactivation', target_type: d.value, target_value: d.value, current_value: 'aktiv', proposed_value: 'inaktiv', reason_template: 'Strategie ' + d.value + ' zeigt bei n=' + n + ' geschlossenen Trades einen Erwartungswert von ' + expR + 'R (deutlich negativ, nicht durch einen Einzeltitel oder ein einzelnes Marktregime dominiert, OOS-bestaetigt).' };
    } else {
      // FIX 2026-08-02 (Fehleranalyse F12): threshold_adjustment hatte denselben NULL-Fehler,
      // aber im Unterschied zu strategy_deactivation existiert hier keine deterministische
      // Formel fuer den Zielwert ("moderat erhoehen" ist keine berechenbare Zahl) - Grundregel
      // 9 verbietet der KI, das selbst zu beziffern. Bewusst deaktiviert statt einen Wert zu
      // erfinden, bis eine echte Formel/Konfiguration entworfen ist (siehe FEHLERANALYSE.md F9).
      candidateProposal = null;
    }
  } else if (eligible && d.dimension === 'strategy_regime' && expR <= -0.15) {
    // FIX 2026-08-01 (Fehleranalyse F5, mittel): vorher wurde hier auch fuer den POSITIVEN
    // Fall (expR >= 0.3, durch "eligible" mit erlaubt) ein 'regime_restriction'-Kandidat mit
    // proposed_value:null erzeugt - semantisch falsch (eine gut performende Kombination als
    // Restriktion vorgeschlagen) und fuehrte spaeter zu einem NOT-NULL-Konflikt beim
    // Speichern. Kandidat entsteht jetzt nur noch fuer den tatsaechlich negativen Fall.
    candidateProposal = { proposal_type: 'regime_restriction', target_type: d.value, target_value: d.sub_value, current_value: null, proposed_value: 0.1, reason_template: 'Strategie ' + d.value + ' im Regime ' + d.sub_value + ' zeigt bei n=' + n + ' Trades einen Erwartungswert von ' + expR + 'R.' };
  }

  findings.push({
    dimension: d.dimension, value: d.value, sub_value: d.sub_value,
    sample_size: n, expectancy_r: expR,
    median_r: d.median_r === null ? null : Number(d.median_r),
    win_rate_pct: d.win_rate_pct === null ? null : Number(d.win_rate_pct),
    profit_factor: d.profit_factor === null ? null : Number(d.profit_factor),
    ambiguous_pct: d.ambiguous_pct === null ? null : Number(d.ambiguous_pct),
    distinct_tickers: Number(d.distinct_tickers) || 0,
    dominiert_von_einem_ticker: dominiertVonEinemTicker,
    confidence_level: level,
    oos_confirmed: oosConfirmed,
    proposal_eligible: eligible && candidateProposal !== null,
    candidate_proposal: candidateProposal
  });
}

return [{ json: {
  analysis_to: getBusinessDate(),
  closed_trades: Number(overall.closed_trades) || 0,
  blocked_trades: Number(overall.blocked_trades) || 0,
  ambiguous_pct_overall: overall.ambiguous_pct === null ? null : Number(overall.ambiguous_pct),
  expectancy_r_overall: overall.expectancy_r === null ? null : Number(overall.expectancy_r),
  profit_factor_overall: overall.profit_factor === null ? null : Number(overall.profit_factor),
  win_rate_pct_overall: overall.win_rate_pct === null ? null : Number(overall.win_rate_pct),
  min_sample_size: MIN_SAMPLE,
  // FIX 2026-08-01 (Fehleranalyse F4, Folgekorrektur): oos_confirmed ist jetzt eine
  // Zusammenfassung (mindestens eine Strategie OOS-bestaetigt) statt des alten globalen
  // Booleans - die tatsaechliche Gate-Pruefung erfolgt je Finding oben (oos_confirmed pro
  // Zeile ueber oosConfirmedFor(d.value)).
  oos_confirmed: oosConfirmedStrategies.size > 0,
  oos_confirmed_strategies: Array.from(oosConfirmedStrategies),
  findings
} }];

const d = $json;
const eligible = d.findings.filter(f => f.proposal_eligible);
const all = d.findings;

const systemPrompt = `Du bist ein vorsichtiger, konservativer Lernagent fuer die Handelsstrategie-Ebene eines
